  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 0.96,
        "text": "那好了"
      },
      {
        "start": 0.96,
        "end": 2.88,
        "text": "這是一張人物原木圖"
      },
      {
        "start": 2.88,
        "end": 4.56,
        "text": "這次我找了服裝和文字"
      },
      {
        "start": 4.56,
        "end": 6.56,
        "text": "我先讓它變成一張變裝視頻"
      },
      {
        "start": 13.68,
        "end": 15.68,
        "text": "這兩個流程都是上週剛出的"
      },
      {
        "start": 15.68,
        "end": 18.16,
        "text": "Meaningless H3模型作出來的"
      },
      {
        "start": 18.16,
        "end": 20.16,
        "text": "嗨 可惜好 先生"
      },
      {
        "start": 20.16,
        "end": 21.28,
        "text": "前面的視頻"
      },
      {
        "start": 21.28,
        "end": 23.36,
        "text": "我全身沒開任何的剪輯軟件"
      },
      {
        "start": 23.36,
        "end": 25.44,
        "text": "隨時 H3 原生生成的"
      },
      {
        "start": 25.44,
        "end": 28.08,
        "text": "這個 H3 不僅定價非常實惠"
      },
      {
        "start": 28.08,
        "end": 29.84,
        "text": "周主流模型的三分之一"
      },
      {
        "start": 29.84,
        "end": 31.28,
        "text": "而且還開緣"
      },
      {
        "start": 31.28,
        "end": 32.64,
        "text": "今天結合我使用後"
      },
      {
        "start": 32.64,
        "end": 33.92,
        "text": "感受最好的幾個亮點"
      },
      {
        "start": 33.92,
        "end": 36.08,
        "text": "跟大家一次性分享一下"
      },
      {
        "start": 36.08,
        "end": 38.48,
        "text": "第一個 綠木換背景"
      },
      {
        "start": 38.48,
        "end": 40.88,
        "text": "開頭短片有個鏡頭就是用這個功能"
      },
      {
        "start": 40.88,
        "end": 42.8,
        "text": "給它一張綠木背景的人物圖"
      },
      {
        "start": 42.8,
        "end": 44.08,
        "text": "再說提示此"
      },
      {
        "start": 44.08,
        "end": 46.48,
        "text": "A&N一間化成你想要的各種場景"
      },
      {
        "start": 47.68,
        "end": 48.88,
        "text": "以前幹這種事"
      },
      {
        "start": 48.88,
        "end": 51.52,
        "text": "大綠木 空向 合成條色"
      },
      {
        "start": 51.52,
        "end": 52.8,
        "text": "上搜索的疙瘩幾天"
      },
      {
        "start": 52.8,
        "end": 55.12,
        "text": "現在 H3居然近一分鐘就搞定"
      },
      {
        "start": 55.12,
        "end": 58.88,
        "text": "最關鍵的是 H3 合成時會自動處理光影"
      },
      {
        "start": 58.88,
        "end": 61.36,
        "text": "絕對順身上的光會跟著背景的光走"
      },
      {
        "start": 61.36,
        "end": 63.84,
        "text": "第二個 孵膽紋們保持"
      },
      {
        "start": 63.84,
        "end": 65.76,
        "text": "之前用的 AI 視頻模型"
      },
      {
        "start": 65.76,
        "end": 68.16,
        "text": "中文還是很明顯斷碼的情況"
      },
      {
        "start": 68.16,
        "end": 70.96000000000001,
        "text": "作為一個字就要全部重新抽卡生成"
      },
      {
        "start": 70.96000000000001,
        "end": 73.28,
        "text": "H3 這次在中文上進步很大"
      },
      {
        "start": 73.28,
        "end": 75.28,
        "text": "想要做這個以由的以外介面"
      },
      {
        "start": 75.28,
        "end": 77.03999999999999,
        "text": "所有文字都是模型自己做的"
      },
      {
        "start": 77.03999999999999,
        "end": 78.16,
        "text": "不是後期皮的"
      },
      {
        "start": 78.16,
        "end": 80.16,
        "text": "這還真正的 AI 原生的例子"
      },
      {
        "start": 83.92,
        "end": 85.64,
        "text": "月色正好"
      },
      {
        "start": 85.64,
        "end": 87.84,
        "text": "不如一起跑到天亮"
      },
      {
        "start": 87.84,
        "end": 89.2,
        "text": "第三個"
      },
      {
        "start": 89.2,
        "end": 90.48,
        "text": "給一段想法"
      },
      {
        "start": 90.48,
        "end": 92.72,
        "text": "一切深層可交付的電影片頭"
      },
      {
        "start": 92.72,
        "end": 94.47999999999999,
        "text": "一切你想做條電影片頭"
      },
      {
        "start": 94.47999999999999,
        "end": 96.72,
        "text": "後期的特效生團隊必不可少"
      },
      {
        "start": 96.72,
        "end": 99.28,
        "text": "現在只需要給一段想法指令"
      },
      {
        "start": 99.28,
        "end": 101.52000000000001,
        "text": "A&N 輕鬆交付一條電影片頭"
      },
      {
        "start": 113.92,
        "end": 115.84,
        "text": "H3 最高還支持15秒"
      },
      {
        "start": 115.84,
        "end": 116.88,
        "text": "2K 增面率"
      },
      {
        "start": 116.88,
        "end": 118.96000000000001,
        "text": "還在原生力領域聲音給予"
      },
      {
        "start": 118.96000000000001,
        "end": 121.28,
        "text": "而且 Mini Max H3 定價便宜"
      },
      {
        "start": 121.28,
        "end": 122.4,
        "text": "是做成本印"
      },
      {
        "start": 122.4,
        "end": 124.08,
        "text": "獲得你隨便強強"
      },
      {
        "start": 124.08,
        "end": 125.36,
        "text": "相當地上的朋友呢"
      },
      {
        "start": 125.36,
        "end": 126.48,
        "text": "你說了一段指令"
      },
      {
        "start": 126.48,
        "end": 128.24,
        "text": "用 AI 就能一件深層"
      },
      {
        "start": 128.24,
        "end": 129.44,
        "text": "程序的小模特"
      },
      {
        "start": 129.44,
        "end": 130.48,
        "text": "搭檢個成本"
      },
      {
        "start": 130.48,
        "end": 131.84,
        "text": "還能自動搭配自模"
      },
      {
        "start": 142.32,
        "end": 143.36,
        "text": "除此之外"
      },
      {
        "start": 143.36,
        "end": 144.72,
        "text": "H3 還開緣了"
      },
      {
        "start": 144.72,
        "end": 145.92000000000002,
        "text": "這位著廣告"
      },
      {
        "start": 145.92000000000002,
        "end": 147.12,
        "text": "地上公司的朋友呢"
      },
      {
        "start": 147.12,
        "end": 148.48,
        "text": "可是先自以部署"
      },
      {
        "start": 148.48,
        "end": 150.72,
        "text": "我想出更適合自己塞到的模型"
      },
      {
        "start": 150.72,
        "end": 151.92000000000002,
        "text": "總提使用下來"
      },
      {
        "start": 151.92000000000002,
        "end": 153.92000000000002,
        "text": "感覺H3的 AI 原生能力呢"
      },
      {
        "start": 153.92000000000002,
        "end": 155.12,
        "text": "能讓大部分的任務"
      },
      {
        "start": 155.12,
        "end": 156.96,
        "text": "以更低的成本實現了"
      },
      {
        "start": 156.96,
        "end": 158.16,
        "text": "我看了這個定價"
      },
      {
        "start": 158.16,
        "end": 159.76,
        "text": "生成二開視頻的費用"
      },
      {
        "start": 159.76,
        "end": 161.52,
        "text": "比市面上同類主流模型"
      },
      {
        "start": 161.52,
        "end": 162.48,
        "text": "也一得多"
      },
      {
        "start": 162.48,
        "end": 164.88,
        "text": "價格跟他們的三分之一"
      },
      {
        "start": 164.88,
        "end": 166.07999999999998,
        "text": "如果你剛好再找一款"
      },
      {
        "start": 166.07999999999998,
        "end": 167.36,
        "text": "更適合廣告"
      },
      {
        "start": 167.36,
        "end": 168,
        "text": "品牌"
      },
      {
        "start": 168,
        "end": 169.68,
        "text": "電商遊戲等場景"
      },
      {
        "start": 169.68,
        "end": 170.4,
        "text": "性價比高"
      },
      {
        "start": 170.4,
        "end": 171.92000000000002,
        "text": "還知道後期能力的模型"
      },
      {
        "start": 171.92000000000002,
        "end": 173.2,
        "text": "可以去試試看"
      }
    ],
